{
  "$schema": "https://wpl.dev/schemas/wpl/v1.schema.json",
  "version": "1.6.0",
  "plan": {
    "id": "postpartum_return_starter",
    "name": "Postpartum Return — 2-Week Starter (4 weeks post-c-section cleared for light activity)",
    "type": "workout",
    "visibility": "private",
    "metadata": {
      "created_at": "2026-06-05T00:00:00Z",
      "created_by": "trainer",
      "language": "en",
      "difficulty": "adaptive",
      "estimated_duration_days": 14,
      "tags": [
        "postpartum",
        "c-section",
        "reconditioning",
        "walking",
        "no_heavy_lifting",
        "no_abs"
      ]
    },
    "goals": [
      {
        "id": "safe_reconditioning",
        "type": "primary",
        "category": "reconditioning",
        "name": "Safe reconditioning and gradual return to activity",
        "description": "Restore general conditioning, pelvic floor awareness, and functional movement while respecting OB clearance: walking and light movement only; no abdominal loading or heavy lifting until 6-week check."
      }
    ],
    "requirements": {
      "min_age": 18,
      "fitness_level": [
        "beginner"
      ],
      "equipment": [
        {
          "id": "yoga_mat",
          "name": "Yoga mat",
          "required": true
        }
      ],
      "contraindications": [
        {
          "condition": "acog:postpartum_c_section_early_rehab",
          "severity": "moderate",
          "action": "modify",
          "affected_activities": [
            "pelvic_tilts",
            "gentle_core_bracing",
            "walking",
            "diaphragmatic_breathing"
          ]
        },
        {
          "condition": "no_abdominal_loading",
          "severity": "high",
          "action": "exclude",
          "affected_activities": [
            "ab_crunches",
            "plank",
            "heavy_lift"
          ]
        }
      ],
      "time_commitment": {
        "min_days_per_week": 3,
        "max_days_per_week": 7,
        "min_minutes_per_day": 10,
        "max_minutes_per_day": 40
      }
    },
    "personalization": {
      "inputs": [
        {
          "id": "pain_at_incision",
          "type": "number",
          "source": "user.reported_pain",
          "label": "Current incision pain (0-10)"
        },
        {
          "id": "days_since_delivery",
          "type": "number",
          "source": "user.days_since_delivery",
          "label": "Days since delivery"
        },
        {
          "id": "energy_level",
          "type": "enum",
          "source": "wellness.subjective_readiness",
          "label": "Subjective energy",
          "options": [
            "low",
            "moderate",
            "high"
          ]
        }
      ],
      "rules": [
        {
          "id": "delay_if_pain",
          "condition": {
            "field": "pain_at_incision",
            "op": "gt",
            "value": 3
          },
          "actions": [
            {
              "type": "modify",
              "scope": "plan",
              "note": "If incision pain >3/10, reduce walking duration by 50% and skip gentle_core_bracing; escalate to provider if pain persists."
            }
          ]
        },
        {
          "id": "scale_by_energy",
          "condition": {
            "field": "energy_level",
            "op": "eq",
            "value": "low"
          },
          "actions": [
            {
              "type": "modify",
              "scope": "day",
              "note": "If energy low, recommend 10–15 minute walk or restorative breathing instead of longer sessions."
            }
          ]
        }
      ]
    },
    "phases": [
      {
        "id": "intro_2_weeks",
        "name": "2-Week Intro Starter",
        "order": 1,
        "type": "recovery",
        "duration": {
          "value": 2,
          "unit": "weeks"
        },
        "weeks": [
          {
            "id": "week_1",
            "name": "Week 1 (post-clearance light activity)",
            "order": 1,
            "days": [
              {
                "id": "w1_d1",
                "day_of_week": 1,
                "type": "training",
                "name": "Walk + breathing",
                "estimated_duration_minutes": 20,
                "blocks": [
                  {
                    "id": "w1_d1_warmup",
                    "type": "warmup",
                    "order": 1,
                    "activities": [
                      {
                        "id": "diaphragmatic_breathing",
                        "type": "meditation",
                        "name": "Diaphragmatic breathing",
                        "category": "breathwork",
                        "prescription": {
                          "duration": {
                            "value": 5,
                            "unit": "minutes"
                          },
                          "guided": false
                        }
                      }
                    ]
                  },
                  {
                    "id": "w1_d1_main",
                    "type": "main",
                    "order": 2,
                    "activities": [
                      {
                        "id": "walk_easy_15",
                        "type": "cardio",
                        "name": "Easy walk (flat terrain)",
                        "modality": "walking",
                        "prescription": {
                          "type": "continuous",
                          "duration": {
                            "value": 15,
                            "unit": "minutes"
                          },
                          "intensity": {
                            "type": "rpe",
                            "target": {
                              "min": 2,
                              "max": 4
                            },
                            "zone_model": "rpe_borg_10"
                          }
                        }
                      }
                    ]
                  }
                ]
              },
              {
                "id": "w1_d2",
                "day_of_week": 2,
                "type": "active_recovery",
                "name": "Restorative mobility",
                "estimated_duration_minutes": 15,
                "blocks": [
                  {
                    "id": "w1_d2_main",
                    "type": "main",
                    "order": 1,
                    "activities": [
                      {
                        "id": "gentle_mobility",
                        "type": "recovery",
                        "name": "Gentle mobility (neck/shoulders/hips)",
                        "category": "mobility",
                        "prescription": {
                          "duration": {
                            "value": 15,
                            "unit": "minutes"
                          },
                          "exercises": [
                            {
                              "id": "neck_rolls",
                              "type": "recovery_exercise",
                              "name": "Neck rolls",
                              "modality": "mobility_drill",
                              "reps": 5,
                              "sides": "both",
                              "intensity_rpe": 3
                            },
                            {
                              "id": "shoulder_pass_throughs",
                              "type": "recovery_exercise",
                              "name": "Shoulder pass-throughs (use towel)",
                              "modality": "mobility_drill",
                              "reps": 8,
                              "sides": "both",
                              "intensity_rpe": 3
                            },
                            {
                              "id": "cat_cow",
                              "type": "recovery_exercise",
                              "name": "Cat-Cow (gentle spinal mobility)",
                              "modality": "mobility_drill",
                              "reps": 8,
                              "sides": "both",
                              "intensity_rpe": 3
                            }
                          ]
                        }
                      }
                    ]
                  }
                ]
              },
              {
                "id": "w1_d3",
                "day_of_week": 3,
                "type": "training",
                "name": "Walk + pelvic floor awareness",
                "estimated_duration_minutes": 25,
                "blocks": [
                  {
                    "id": "w1_d3_warmup",
                    "type": "warmup",
                    "order": 1,
                    "activities": [
                      {
                        "id": "diaphragmatic_breathing_2",
                        "type": "meditation",
                        "name": "Diaphragmatic breathing with pelvic floor cue",
                        "category": "breathwork",
                        "prescription": {
                          "duration": {
                            "value": 5,
                            "unit": "minutes"
                          },
                          "guided": false
                        }
                      }
                    ]
                  },
                  {
                    "id": "w1_d3_main",
                    "type": "main",
                    "order": 2,
                    "activities": [
                      {
                        "id": "walk_brisk_15",
                        "type": "cardio",
                        "name": "Brisk walk (comfortably brisk)",
                        "modality": "walking",
                        "prescription": {
                          "type": "continuous",
                          "duration": {
                            "value": 15,
                            "unit": "minutes"
                          },
                          "intensity": {
                            "type": "rpe",
                            "target": {
                              "min": 3,
                              "max": 5
                            },
                            "zone_model": "rpe_borg_10"
                          }
                        }
                      },
                      {
                        "id": "pelvic_floor_gentle",
                        "type": "habit",
                        "name": "Gentle pelvic floor engagement practice",
                        "category": "pelvic_floor",
                        "prescription": {
                          "frequency": "daily",
                          "target": {
                            "value": 6,
                            "unit": "reps"
                          },
                          "reminders": [
                            "after_walking",
                            "evening"
                          ]
                        },
                        "tracking": {
                          "notes": "Short gentle squeezes (not bearing down). Stop if pain or heaviness."
                        }
                      }
                    ]
                  }
                ]
              },
              {
                "id": "w1_d4",
                "day_of_week": 4,
                "type": "rest",
                "name": "Rest day",
                "estimated_duration_minutes": 0
              },
              {
                "id": "w1_d5",
                "day_of_week": 5,
                "type": "training",
                "name": "Short walk + upright mobility",
                "estimated_duration_minutes": 20,
                "blocks": [
                  {
                    "id": "w1_d5_main",
                    "type": "main",
                    "order": 1,
                    "activities": [
                      {
                        "id": "walk_easy_20",
                        "type": "cardio",
                        "name": "Easy walk",
                        "modality": "walking",
                        "prescription": {
                          "type": "continuous",
                          "duration": {
                            "value": 20,
                            "unit": "minutes"
                          },
                          "intensity": {
                            "type": "rpe",
                            "target": {
                              "min": 2,
                              "max": 4
                            },
                            "zone_model": "rpe_borg_10"
                          }
                        }
                      },
                      {
                        "id": "upright_mobility",
                        "type": "recovery",
                        "name": "Standing hip circles & ankle mobility",
                        "category": "mobility",
                        "prescription": {
                          "duration": {
                            "value": 5,
                            "unit": "minutes"
                          },
                          "exercises": [
                            {
                              "id": "hip_circles",
                              "type": "recovery_exercise",
                              "name": "Hip circles (standing)",
                              "modality": "mobility_drill",
                              "reps": 6,
                              "sides": "both",
                              "intensity_rpe": 3
                            },
                            {
                              "id": "ankle_pumps",
                              "type": "recovery_exercise",
                              "name": "Ankle pumps",
                              "modality": "mobility_drill",
                              "reps": 20,
                              "sides": "both",
                              "intensity_rpe": 2
                            }
                          ]
                        }
                      }
                    ]
                  }
                ]
              },
              {
                "id": "w1_d6",
                "day_of_week": 6,
                "type": "active_recovery",
                "name": "Restorative stretching",
                "estimated_duration_minutes": 15,
                "blocks": [
                  {
                    "id": "w1_d6_main",
                    "type": "main",
                    "order": 1,
                    "activities": [
                      {
                        "id": "gentle_stretching",
                        "type": "recovery",
                        "name": "Gentle stretching (hamstrings, quads, glutes)",
                        "category": "static_stretch",
                        "prescription": {
                          "duration": {
                            "value": 15,
                            "unit": "minutes"
                          },
                          "exercises": [
                            {
                              "id": "seated_hamstring",
                              "type": "recovery_exercise",
                              "name": "Seated hamstring stretch",
                              "modality": "static_stretch",
                              "hold_seconds": 30,
                              "reps": 2,
                              "sides": "both",
                              "intensity_rpe": 5
                            },
                            {
                              "id": "figure_four",
                              "type": "recovery_exercise",
                              "name": "Figure-four glute stretch",
                              "modality": "static_stretch",
                              "hold_seconds": 30,
                              "reps": 2,
                              "sides": "both",
                              "intensity_rpe": 5
                            }
                          ]
                        }
                      }
                    ]
                  }
                ]
              },
              {
                "id": "w1_d7",
                "day_of_week": 7,
                "type": "rest",
                "name": "Rest / optional short walk",
                "estimated_duration_minutes": 10,
                "blocks": [
                  {
                    "id": "w1_d7_main",
                    "type": "main",
                    "order": 1,
                    "activities": [
                      {
                        "id": "optional_walk_10",
                        "type": "cardio",
                        "name": "Optional short walk",
                        "modality": "walking",
                        "prescription": {
                          "type": "continuous",
                          "duration": {
                            "value": 10,
                            "unit": "minutes"
                          },
                          "intensity": {
                            "type": "rpe",
                            "target": {
                              "min": 2,
                              "max": 4
                            },
                            "zone_model": "rpe_borg_10"
                          }
                        }
                      }
                    ]
                  }
                ]
              }
            ]
          },
          {
            "id": "week_2",
            "name": "Week 2 (progress lightly as tolerated)",
            "order": 2,
            "days": [
              {
                "id": "w2_d1",
                "day_of_week": 1,
                "type": "training",
                "name": "Walk + breathing",
                "estimated_duration_minutes": 25,
                "blocks": [
                  {
                    "id": "w2_d1_warmup",
                    "type": "warmup",
                    "order": 1,
                    "activities": [
                      {
                        "id": "diaphragmatic_breathing_3",
                        "type": "meditation",
                        "name": "Diaphragmatic breathing",
                        "category": "breathwork",
                        "prescription": {
                          "duration": {
                            "value": 5,
                            "unit": "minutes"
                          },
                          "guided": false
                        }
                      }
                    ]
                  },
                  {
                    "id": "w2_d1_main",
                    "type": "main",
                    "order": 2,
                    "activities": [
                      {
                        "id": "walk_20",
                        "type": "cardio",
                        "name": "Walk (steady)",
                        "modality": "walking",
                        "prescription": {
                          "type": "continuous",
                          "duration": {
                            "value": 20,
                            "unit": "minutes"
                          },
                          "intensity": {
                            "type": "rpe",
                            "target": {
                              "min": 3,
                              "max": 5
                            },
                            "zone_model": "rpe_borg_10"
                          }
                        }
                      }
                    ]
                  }
                ]
              },
              {
                "id": "w2_d2",
                "day_of_week": 2,
                "type": "active_recovery",
                "name": "Pelvic floor & gentle core awareness",
                "estimated_duration_minutes": 15,
                "blocks": [
                  {
                    "id": "w2_d2_main",
                    "type": "main",
                    "order": 1,
                    "activities": [
                      {
                        "id": "gentle_core_bracing",
                        "type": "habit",
                        "name": "Gentle core awareness (no abdominal strain)",
                        "category": "core_retraining",
                        "prescription": {
                          "frequency": "daily",
                          "target": {
                            "value": 5,
                            "unit": "breaths"
                          },
                          "reminders": [
                            "morning",
                            "evening"
                          ]
                        },
                        "tracking": {
                          "notes": "Gentle transverse activation with exhale; avoid Valsalva and crunching. Stop if any pulling or pain at incision."
                        }
                      },
                      {
                        "id": "thoracic_mobilization",
                        "type": "recovery",
                        "name": "Thoracic opening drills",
                        "category": "mobility",
                        "prescription": {
                          "duration": {
                            "value": 10,
                            "unit": "minutes"
                          },
                          "exercises": [
                            {
                              "id": "thread_the_needle",
                              "type": "recovery_exercise",
                              "name": "Thread-the-needle",
                              "modality": "mobility_drill",
                              "reps": 8,
                              "sides": "both",
                              "intensity_rpe": 3
                            }
                          ]
                        }
                      }
                    ]
                  }
                ]
              },
              {
                "id": "w2_d3",
                "day_of_week": 3,
                "type": "training",
                "name": "Walk intervals (gentle)",
                "estimated_duration_minutes": 30,
                "blocks": [
                  {
                    "id": "w2_d3_main",
                    "type": "main",
                    "order": 1,
                    "activities": [
                      {
                        "id": "walk_intervals",
                        "type": "cardio",
                        "name": "Walk intervals: 3x (5min walk + 1-2min easy)",
                        "modality": "walking",
                        "prescription": {
                          "type": "intervals",
                          "duration": {
                            "value": 30,
                            "unit": "minutes"
                          },
                          "intensity": {
                            "type": "rpe",
                            "target": {
                              "min": 3,
                              "max": 5
                            },
                            "zone_model": "rpe_borg_10"
                          },
                          "intervals": {
                            "work": {
                              "duration": {
                                "value": 300,
                                "unit": "seconds"
                              }
                            },
                            "rest": {
                              "duration": {
                                "value": 120,
                                "unit": "seconds"
                              }
                            },
                            "repeat": 3
                          }
                        }
                      }
                    ]
                  }
                ]
              },
              {
                "id": "w2_d4",
                "day_of_week": 4,
                "type": "rest",
                "name": "Rest day"
              },
              {
                "id": "w2_d5",
                "day_of_week": 5,
                "type": "training",
                "name": "Longer walk + mobility",
                "estimated_duration_minutes": 30,
                "blocks": [
                  {
                    "id": "w2_d5_main",
                    "type": "main",
                    "order": 1,
                    "activities": [
                      {
                        "id": "walk_30",
                        "type": "cardio",
                        "name": "Steady walk",
                        "modality": "walking",
                        "prescription": {
                          "type": "continuous",
                          "duration": {
                            "value": 30,
                            "unit": "minutes"
                          },
                          "intensity": {
                            "type": "rpe",
                            "target": {
                              "min": 3,
                              "max": 5
                            },
                            "zone_model": "rpe_borg_10"
                          }
                        }
                      },
                      {
                        "id": "ankle_hip_mobility",
                        "type": "recovery",
                        "name": "Ankle + hip mobility",
                        "category": "mobility",
                        "prescription": {
                          "duration": {
                            "value": 5,
                            "unit": "minutes"
                          },
                          "exercises": [
                            {
                              "id": "hip_opener",
                              "type": "recovery_exercise",
                              "name": "Standing hip opener",
                              "modality": "mobility_drill",
                              "reps": 6,
                              "sides": "both",
                              "intensity_rpe": 3
                            }
                          ]
                        }
                      }
                    ]
                  }
                ]
              },
              {
                "id": "w2_d6",
                "day_of_week": 6,
                "type": "active_recovery",
                "name": "Breathing + light mobility",
                "estimated_duration_minutes": 15,
                "blocks": [
                  {
                    "id": "w2_d6_main",
                    "type": "main",
                    "order": 1,
                    "activities": [
                      {
                        "id": "breath_and_mobility",
                        "type": "meditation",
                        "name": "Breath awareness + gentle mobility",
                        "category": "breathwork",
                        "prescription": {
                          "duration": {
                            "value": 15,
                            "unit": "minutes"
                          },
                          "guided": false
                        }
                      }
                    ]
                  }
                ]
              },
              {
                "id": "w2_d7",
                "day_of_week": 7,
                "type": "rest",
                "name": "Rest / optional mini-walk",
                "estimated_duration_minutes": 10,
                "blocks": [
                  {
                    "id": "w2_d7_main",
                    "type": "main",
                    "order": 1,
                    "activities": [
                      {
                        "id": "optional_walk_10_w2",
                        "type": "cardio",
                        "name": "Optional short walk",
                        "modality": "walking",
                        "prescription": {
                          "type": "continuous",
                          "duration": {
                            "value": 10,
                            "unit": "minutes"
                          },
                          "intensity": {
                            "type": "rpe",
                            "target": {
                              "min": 2,
                              "max": 4
                            },
                            "zone_model": "rpe_borg_10"
                          }
                        }
                      }
                    ]
                  }
                ]
              }
            ]
          }
        ]
      }
    ],
    "progress": {
      "checkpoints": [
        {
          "id": "two_week_checkin",
          "name": "2-week check-in",
          "at": {
            "value": 14,
            "unit": "days"
          },
          "measurements": [
            "user-reported energy",
            "user-reported incision pain",
            {
              "metric": "questionnaire_score",
              "questionnaire": "rpe_session",
              "note": "Session RPE average over 2 weeks"
            }
          ],
          "questions": [
            "Any new or worsening pain at incision site?",
            "Any urinary or pelvic organ heaviness?",
            "How would you rate overall energy (low/moderate/high)?"
          ]
        }
      ]
    }
  }
}
